const G=9.8,N=60,TG=[30,45,18],R=1.2,D=Math.PI/180;
function pos(a,v,t){return [v*Math.cos(a*D)*t,Math.max(0,v*Math.sin(a*D)*t-G*t*t/2)+R,0];}
function tf(a,v){return 2*v*Math.sin(a*D)/G;}
function pts(a,v,p){const T=tf(a,v),n=Math.max(2,Math.round(40*p)+1),o=[];for(let i=0;i<n;i++)o.push(pos(a,v,T*p*i/(n-1)));return o;}
export function initialState(){return {fly:false,k:0,a:45,v:15,shots:0,hits:0,ti:0,last:null,prev:null};}
export function reduce({state,event,inputs}){const s=state;
if(event.type==='action'&&event.action==='launch'){if(s.fly||s.hits>=3||s.shots>=10)return s;return {...s,fly:true,k:0,a:inputs.angle,v:inputs.speed,prev:s.last?{a:s.last.a,v:s.last.v}:s.prev};}
if(event.type==='step'&&s.fly){const k=s.k+1;if(k<N)return {...s,k};const d=s.v*s.v*Math.sin(2*s.a*D)/G,tx=TG[s.ti],m=d-tx,hit=Math.abs(m)<=1.5;return {...s,fly:false,k:N,shots:s.shots+1,hits:s.hits+(hit?1:0),ti:s.ti+(hit?1:0),last:{a:s.a,v:s.v,d,m,hit,tx}};}
return s;}
export function evaluate({inputs,state}){const s=state,L=s.last,th=-(90-inputs.angle)*D;
const nodes={pivot:{quaternion:[0,0,Math.sin(th/2),Math.cos(th/2)]},target:{position:[TG[Math.min(s.ti,2)],0,0]}};
let bp=[0,R,0];if(s.fly){bp=pos(s.a,s.v,tf(s.a,s.v)*s.k/N);nodes.trail={visible:true,points:pts(s.a,s.v,s.k/N)};}else if(L){bp=[L.d,R,0];nodes.trail={visible:true,points:pts(L.a,L.v,1)};}else nodes.trail={visible:false};
nodes.ball={position:bp};nodes.ghost=s.prev?{visible:true,points:pts(s.prev.a,s.prev.v,1)}:{visible:false};
const r={shots:s.shots,hits:s.hits};if(L){r.dist=L.d;r.miss=Math.abs(L.m);r.side=L.hit?'hit':(L.m<0?'short':'long');r.ftime=tf(L.a,L.v);r.hmax=Math.pow(L.v*Math.sin(L.a*D),2)/(2*G);}
let goal;const left=10-s.shots;
if(s.hits>=3)goal={status:'won',message:'You hit all 3 targets in '+s.shots+' launches!'};
else if(left<=0&&!s.fly)goal={status:'lost',message:'Out of launches: '+s.hits+' of 3 targets hit.'};
else{let m='Target '+(s.ti+1)+' of 3 at '+TG[s.ti]+' m. Launches left: '+left+'.';if(L&&!s.fly)m=(L.hit?'Hit! ':'Missed: '+Math.abs(L.m).toFixed(1)+' m '+(L.m<0?'short. ':'long. '))+m;goal={status:'playing',message:m};}
return {nodes,readouts:r,goal};}
